'use strict';

const { Client }  = require('./Client');
const { Account } = require('./resources/Account');
const { Airtime } = require('./resources/Airtime');
const { Data }    = require('./resources/Data');

class Strongmb {
    constructor(apiKey, { sandbox = false } = {}) {
        const client  = new Client(apiKey, sandbox);
        this.account  = new Account(client);
        this.airtime  = new Airtime(client);
        this.data     = new Data(client);
    }
}

module.exports = { Strongmb };
